--

CREATE TABLE public.kb_articles (
    id bigint NOT NULL,
    folder_id bigint NOT NULL,
    slug character varying(255) NOT NULL,
    title character varying(500) NOT NULL,
    locale character varying(8) DEFAULT 'en'::character varying NOT NULL,
    classification character varying(32) NOT NULL,
    status character varying(32) DEFAULT 'draft'::character varying NOT NULL,
    is_ai_groundable boolean DEFAULT false NOT NULL,
    body_html text DEFAULT ''::text NOT NULL,
    body_tiptap_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    body_markdown text DEFAULT ''::text NOT NULL,
    author_user_id bigint,
    published_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    body_tsvector tsvector GENERATED ALWAYS AS (
CASE locale
    WHEN 'de'::text THEN to_tsvector('german'::regconfig, (((COALESCE(title, ''::character varying))::text || ' '::text) || COALESCE(body_markdown, ''::text)))
    WHEN 'en'::text THEN to_tsvector('english'::regconfig, (((COALESCE(title, ''::character varying))::text || ' '::text) || COALESCE(body_markdown, ''::text)))
    ELSE to_tsvector('simple'::regconfig, (((COALESCE(title, ''::character varying))::text || ' '::text) || COALESCE(body_markdown, ''::text)))
END) STORED,
    CONSTRAINT constraint_kb_articles_on_classification CHECK (((classification)::text = ANY ((ARRAY['faq'::character varying, 'how_to'::character varying, 'policy'::character varying, 'news'::character varying, 'other'::character varying])::text[]))),
    CONSTRAINT constraint_kb_articles_on_status CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'published'::character varying])::text[])))
);


