--
-- Name: worklogs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.worklogs (
    id bigint NOT NULL,
    conversation_id bigint NOT NULL,
    user_id bigint,
    started_at timestamp with time zone NOT NULL,
    ended_at timestamp with time zone,
    duration_seconds integer,
    action_type character varying(32) NOT NULL,
    automation_level character varying(2) DEFAULT 'L0'::character varying NOT NULL,
    context jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT constraint_worklogs_on_action_type CHECK (((action_type)::text = ANY ((ARRAY['write'::character varying, 'status'::character varying, 'note'::character varying, 'forward'::character varying])::text[]))),
    CONSTRAINT constraint_worklogs_on_automation_level CHECK (((automation_level)::text = ANY ((ARRAY['L0'::character varying, 'L1'::character varying, 'L2'::character varying, 'L3'::character varying, 'L4'::character varying, 'L5'::character varying])::text[]))),
    CONSTRAINT constraint_worklogs_on_duration_non_negative CHECK (((duration_seconds IS NULL) OR (duration_seconds >= 0))),
    CONSTRAINT constraint_worklogs_on_ended_at_after_started_at CHECK (((ended_at IS NULL) OR (ended_at >= started_at)))
);


