ress\\": \\"Lukas Weber, Kastanienallee 47, 10435 Berlin / Prenzlauer Berg\\",\\n    \\"desiredDateOfTransition\\": \\"2024-02-01\\",\\n    \\"draftCreatedAt\\": \\"2023-12-18 13:50\\",\\n    \\"durationPeriod\\": 12,\\n    \\"durationPeriodUnit\\": \\"Month\\",\\n    \\"email\\": \\"[EMAIL]\\",\\n    \\"endOfDelivery\\": null,\\n    \\"erp_urls\\": [\\n      {\\n        \\"label\\": \\"ERP\\",\\n        \\"logo\\": null,\\n        \\"url\\": \\"https://erp.example.com/contracts/C-880011\\"\\n      }\\n    ],\\n    \\"firstname\\": \\"Lukas\\",\\n    \\"fullname\\": \\"Lukas Weber\\",\\n    \\"hasElectricVehicle\\": false,\\n    \\"hasHeatPump\\": true,\\n    \\"hasJiraTickets\\": false,\\n    \\"hasOpenFirstLevelEvents\\": false,\\n    \\"hasSmartMeter\\": true,\\n    \\"hasWallBox\\": false,\\n    \\"houseNumber\\": \\"47\\",\\n    \\"iban\\": \\"DE89**************4521\\",\\n    \\"isBillingPermanentlyDisabled\\": false,\\n    \\"isConsideredInBilling\\": true,\\n    \\"isRlm\\": false,\\n    \\"jiraTickets\\": [],\\n    \\"lastManualChangeProcess\\": null,\\n    \\"lastProcessAnswerCode\\": \\"A51\\",\\n    \\"lastProcessAnswerDescription\\": \\"Bestätigung der Anmeldung\\",\\n    \\"lastProcessAnswerType\\": \\"Accepted\\",\\n    \\"lastProcessCreatedAt\\": \\"2023-12-18 22:10\\",\\n    \\"lastProcessTransactionReason\\": \\"E01\\",\\n    \\"lastProcessType\\": \\"Registration\\",\\n    \\"last_synced_at\\": \\"2026-05-30T18:36:19.513013Z\\",\\n    \\"lastname\\": \\"Weber\\",\\n    \\"marketLocationIdentifier\\": \\"50872319104\\",\\n    \\"meterNumber\\": \\"1ESY1160234712\\",\\n    \\"meteringLocationIdentifier\\": \\"[IBAN]\\",\\n    \\"phone\\": \\"[PHONE]\\",\\n    \\"renewalPeriod\\": 12,\\n    \\"renewalPeriodUnit\\": \\"Month\\",\\n    \\"salutation\\": \\"Herr\\",\\n    \\"signedAt\\": \\"2023-12-18 14:22\\",\\n    \\"siteKey\\": 12104872,\\n    \\"startOfDelivery\\": \\"2024-02-01 00:00\\",\\n    \\"street\\": \\"Kastanienallee\\",\\n    \\"tabPreview