1	2026-05-25 23:50:19.08417+00	2026-05-28 14:05:26.175122+00	search_customer_by_fields	customer_identification	import sdk\n\ncontract_id = sdk.input.get("contractId")\ncustomer_id = sdk.input.get("customerId")\nfirstname   = (sdk.input.get("firstname") or "").lower().strip()\nlastname    = (sdk.input.get("lastname") or "").lower().strip()\nemail       = (sdk.input.get("email") or "").lower().strip()\nphone       = (sdk.input.get("phone") or "").strip()\ncompany     = (sdk.input.get("company") or "").lower().strip()\n\n# Direct ID lookups win immediately\ncontract_to_customer = {\n    "C-880011": "K-100023",\n    "C-880042": "K-100023",\n    "C-880117": "K-100087",\n    "C-880204": "K-100156",\n}\ncustomer_to_first_contract = {\n    "K-100023": "C-880011",\n    "K-100087": "C-880117",\n    "K-100156": "C-880204",\n}\n\nif contract_id and contract_id in contract_to_customer:\n    sdk.success(data={\n        "contractId": contract_id,\n        "customerId": contract_to_customer[contract_id],\n    })\n    raise SystemExit\n\nif customer_id and customer_id in customer_to_first_contract:\n    sdk.success(data={\n        "contractId": customer_to_first_contract[customer_id],\n        "customerId": customer_id,\n    })\n    raise SystemExit\n\n# Customer directory for attribute matching\ncustomers = [\n    {\n        "id": "K-100023",\n        "first_contract": "C-880011",\n        "firstname": "lukas",\n        "lastname": "weber",\n        "email": "lukas.weber@example.com",\n        "phone_digits": "491701234567",\n        "company": None,\n    },\n    {\n        "id": "K-100087",\n        "first_contract": "C-880117",\n        "firstname": None,\n        "lastname": None,\n        "email": "kontakt@baeckerei-schneider.example.com",\n        "phone_digits": "49899876543",\n        "company": "bäckerei schneider gmbh",\n    },\n    {\n        "id": "K-100156",\n        "first_contract": "C-880204",\n        "firstname": "sophie",\n        "lastname": "becker",\n        "email": "sophie.becker@example.com",\n        "phone_digits": "491515556789",\n        "company": None,\n    },\n]\n\ndef phone_digits(s):\n    return "".join(c for c in (s or "") if c.isdigit())\n\ninput_phone_digits = phone_digits(phone)\n\ndef score(c):\n    s = 0\n    # Email match is the strongest signal\n    if email and c["email"] and email == c["email"]:\n        s += 10\n    # Name matching (both parts together is strong; one part is weak)\n    if firstname and c["firstname"] and firstname == c["firstname"]:\n        s += 3\n    if lastname and c["lastname"] and lastname == c["lastname"]:\n        s += 3\n    # Company match (substring works for "schneider" → "bäckerei schneider gmbh")\n    if company and c["company"] and (company in c["company"] or c["company"] in company):\n        s += 5\n    # Phone match by digits-only (handles formatting variations)\n    if input_phone_digits and c["phone_digits"] and input_phone_digits == c["phone_digits"]:\n        s += 5\n    return s\n\nscored = [(score(c), c) for c in customers]\nscored = [item for item in scored if item[0] >= 3]  # at least one strong-ish signal\nscored.sort(key=lambda x: -x[0])\n\nif scored:\n    best = scored[0][1]\n    sdk.success(data={\n        "contractId": best["first_contract"],\n        "customerId": best["id"],\n    })\nelse:\n    sdk.failure("no customer matched the given attributes", code="NOT_FOUND")	python		30000	[{"id": "11111111-1111-4111-8111-000000000001", "key": "firstname", "value": "sophie"}, {"id": "11111111-1111-4111-8111-000000000002", "key": "lastname", "value": "becker"}]	1
